	@Test
	void severeMissQuarantinesUntilEightAcceptedRebuildSamples() {
		LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel();
		LmdbNativePhysicalVariantKey key = key("hash", 7);
		LmdbNativeCostVector one = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.HASH_PROBE, 1);
		store.update(key, one, one, 10, 10_000, true);
		assertTrue(store.correction(key).quarantined());
		for (int i = 0; i < LmdbNativeStoreCostModel.QUARANTINE_REBUILD_SAMPLES - 1; i++) {
			store.update(key, one, one, 10, 10, false);
			assertTrue(store.correction(key).quarantined());
		}
		store.update(key, one, one, 10, 10, false);
		assertFalse(store.correction(key).quarantined());
	}

	@Test
	void partialObservationTrainsOnceAndKeepsStartup() {
		LmdbNativeMachineCostModel machine = new LmdbNativeMachineCostModel();
		LmdbNativeAdaptiveCostModel model = model(machine, new LmdbNativeStoreCostModel());
		LmdbNativeCostVector startup = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.OPEN, 1);
		LmdbNativeCostVector total = startup.plus(
				LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.GENERATED_ROW, 100));
		LmdbNativeCostEstimate estimate = new LmdbNativeCostEstimate(key("generated", 4), startup, total, 100, 0.1);
		FakeClock clock = new FakeClock();
		LmdbNativeCostObservation observation = new LmdbNativeCostObservation(estimate, model, clock);
		clock.advance(10);
		observation.firstOutput();
		observation.add(LmdbNativeCostVector.Feature.OPEN, 1);
		observation.add(LmdbNativeCostVector.Feature.GENERATED_ROW, 25);
		clock.advance(90);
		observation.expectedEarlyClose(0.25);
		observation.close();

		LmdbNativeCostObservation.Snapshot snapshot = observation.snapshot();
		assertEquals(LmdbNativeCostObservation.Completion.EXPECTED_EARLY_CLOSE, snapshot.completion());
		assertEquals(10, snapshot.startupNanos());
		assertEquals(100, snapshot.totalNanos());
		assertEquals(0.25, snapshot.consumedFraction());
		assertTrue(snapshot.trainingResult().trained());
		assertEquals(1, machine.snapshot().sampleCount());
	}

	@Test
	void failuresCancellationFallbackAndUnexplainedCloseDoNotTrain() {
		for (LmdbNativeCostObservation.Completion completion : List.of(LmdbNativeCostObservation.Completion.FAILED,
				LmdbNativeCostObservation.Completion.CANCELLED, LmdbNativeCostObservation.Completion.FALLBACK,
				LmdbNativeCostObservation.Completion.DECLINED,
				LmdbNativeCostObservation.Completion.UNEXPLAINED_EARLY_CLOSE)) {
			LmdbNativeMachineCostModel machine = new LmdbNativeMachineCostModel();
			LmdbNativeAdaptiveCostModel model = model(machine, new LmdbNativeStoreCostModel());
			LmdbNativeCostObservation observation = new LmdbNativeCostObservation(
					estimate(key("reject", completion.ordinal()), LmdbNativeCostVector.Feature.OPEN, 1), model,
					new FakeClock());
			switch (completion) {
			case FAILED -> observation.failed(new IllegalStateException("test"));
			case CANCELLED -> observation.cancelled(new RuntimeException("cancel"));
			case FALLBACK -> observation.fallback();
			case DECLINED -> observation.declined();
			case UNEXPLAINED_EARLY_CLOSE -> observation.close();
			default -> throw new AssertionError(completion);
			}
			observation.close();
			assertEquals(0, machine.snapshot().sampleCount(), completion.name());
			assertTrue(observation.isComplete());
		}
	}

	@Test
	void concurrentCompletionUpdatesPublishSafeSnapshots() throws Exception {
		LmdbNativeMachineCostModel machine = new LmdbNativeMachineCostModel();
		LmdbNativeCostVector rows = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.BATCH_ROW, 100);
		ExecutorService executor = Executors.newFixedThreadPool(8);
		try {
			List<Callable<Void>> tasks = new ArrayList<>();
			for (int i = 0; i < 256; i++) {
				tasks.add(() -> {
					machine.update(rows, 10_000);
					assertTrue(machine.predict(rows).expectedNanos() >= 0.0);
					return null;
				});
			}
			for (Future<Void> future : executor.invokeAll(tasks)) {
				future.get();
			}
		} finally {
			executor.shutdownNow();
		}
		assertEquals(256, machine.snapshot().sampleCount());
	}

	private static LmdbNativeAdaptiveCostModel model(LmdbNativeMachineCostModel machine,
			LmdbNativeStoreCostModel store) {
		return new LmdbNativeAdaptiveCostModel(machine, store,
				new LmdbNativeAdaptiveCostModel.Configuration(true, true, true, 10));
	}

	private static LmdbNativeCostEstimate estimate(LmdbNativePhysicalVariantKey key,
			LmdbNativeCostVector.Feature feature, double count) {
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(feature, count);
		return new LmdbNativeCostEstimate(key, LmdbNativeCostVector.zero(), vector, count, 0.1);
	}

	private static LmdbNativePhysicalVariantKey key(String family, long fingerprint) {
		return LmdbNativePhysicalVariantKey.builder(family)
				.structuralOperatorFingerprint(fingerprint)
				.physicalOrderAndProperties("order")
				.build();
	}

	private static final class FakeClock implements LmdbNativeCostObservation.NanoClock {
		private final AtomicLong now = new AtomicLong();

		@Override
		public long nanoTime() {
			return now.get();
		}

		void advance(long nanos) {
			now.addAndGet(nanos);
		}
	}
